/// Icon from a web class name such as `fa-clipboard-list` (stored in notifications / statuses).
IconData fa(String? name) {
  if (name == null || name.isEmpty) return FA.circleInfo;
  final key = name.trim().split(' ').first;
  return FA.byName[key.startsWith('fa-') ? key.substring(3) : key] ?? FA.circleInfo;
}
